// Generated by AI (UnitTest MCP)
import assert from "node:assert/strict";
import { mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";

import {
  EXPECTED_HOOKS,
  healthMessage,
  isPreCommitHook,
  missingHooks,
  readHookFrom,
  setupCommand,
} from "./hook-health.mjs";

// A pre-commit generated hook names itself; that is the marker we key on.
const PRE_COMMIT_SHIM =
  "#!/usr/bin/env bash\n# File generated by pre-commit: https://pre-commit.com\nexec pre-commit hook-impl --hook-type=post-commit\n";

/** A throwaway hooks directory, so no test reads the repository's real hooks. */
const withHooksDir = (files, run) => {
  const dir = mkdtempSync(join(tmpdir(), "hook-health-"));
  try {
    for (const [name, body] of Object.entries(files)) {
      writeFileSync(join(dir, name), body, "utf8");
    }
    run(dir);
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
};

test("a file that names pre-commit is an installed hook; anything else is not", () => {
  assert.equal(isPreCommitHook(PRE_COMMIT_SHIM), true);
  assert.equal(isPreCommitHook(null), false, "absent");
  assert.equal(
    isPreCommitHook("#!/bin/sh\necho hand-written\n"),
    false,
    "a hand-written hook does not run pre-commit's stages",
  );
});

test("a complete installation reports nothing missing", () => {
  const reader = () => PRE_COMMIT_SHIM;
  assert.deepEqual(missingHooks(reader), []);
});

test("a missing post-commit is named, and only it", () => {
  // The exact drift this guard exists to catch: pre-commit and pre-push were
  // installed before post-commit joined default_install_hook_types, so commits
  // land with no provenance and nothing says so.
  const reader = (hook) => (hook === "post-commit" ? null : PRE_COMMIT_SHIM);
  assert.deepEqual(missingHooks(reader), ["post-commit"]);
});

test("a hook file that exists but is not pre-commit's counts as missing", () => {
  const reader = (hook) =>
    hook === "pre-push" ? "#!/bin/sh\necho stale\n" : PRE_COMMIT_SHIM;
  assert.deepEqual(missingHooks(reader), ["pre-push"]);
});

test("the message names every missing hook and the one repair command", () => {
  const message = healthMessage(["pre-commit", "post-commit"]);
  assert.match(message, /- pre-commit/);
  assert.match(message, /- post-commit/);
  assert.ok(
    message.includes(setupCommand()),
    "an actionable setup command, not just a complaint",
  );
});

test("reading a complete hooks directory off disk finds nothing missing", () => {
  withHooksDir(
    {
      "pre-commit": PRE_COMMIT_SHIM,
      "pre-push": PRE_COMMIT_SHIM,
      "post-commit": PRE_COMMIT_SHIM,
    },
    (dir) => {
      assert.deepEqual(missingHooks(readHookFrom(dir)), []);
    },
  );
});

test("reading a hooks directory that lacks post-commit names it", () => {
  withHooksDir(
    {
      "pre-commit": PRE_COMMIT_SHIM,
      "pre-push": PRE_COMMIT_SHIM,
    },
    (dir) => {
      assert.deepEqual(missingHooks(readHookFrom(dir)), ["post-commit"]);
    },
  );
});

test("the expected set is exactly the three declared hook types", () => {
  assert.deepEqual(EXPECTED_HOOKS, ["pre-commit", "pre-push", "post-commit"]);
});
